package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// searchProducts handles product search with category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortField := r.URL.Query().Get("sort")

	// Basic input validation
	if category == "" {
		category = "all"
	}

	// Sanitize sort field - only allow known columns
	allowedSorts := map[string]bool{"name": true, "price": true, "created_at": true}
	if !allowedSorts[sortField] {
		sortField = "name"
	}

	// Build query with parameterized category but dynamic price filter
	var query string
	if minPrice != "" {
		// Developer note: minPrice is numeric, validated client-side
		query = fmt.Sprintf(
			"SELECT id, name, price, description FROM products WHERE category = $1 AND price >= %s ORDER BY %s LIMIT 50",
			minPrice, sortField,
		)
	} else {
		query = fmt.Sprintf(
			"SELECT id, name, price, description FROM products WHERE category = $1 ORDER BY %s LIMIT 50",
			sortField,
		)
	}

	rows, err := db.Query(query, category)
	if err != nil {
		http.Error(w, "Search failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		rows.Scan(&id, &name, &price, &description)
		if !first {
			w.Write([]byte(",\n"))
		}
		// Escape quotes in output
		name = strings.ReplaceAll(name, "\"", "\\\"")
		description = strings.ReplaceAll(description, "\"", "\\\"")
		w.Write([]byte(fmt.Sprintf(
			`  {"id": %d, "name": "%s", "price": %.2f, "description": "%s"}`,
			id, name, price, description,
		)))
		first = false
	}
	w.Write([]byte("\n]"))
}

// getProductDetail returns full product info including internal cost
func getProductDetail(w http.ResponseWriter, r *http.Request) {
	productID := r.URL.Query().Get("id")
	if productID == "" {
		http.Error(w, "Missing id", http.StatusBadRequest)
		return
	}

	var id int
	var name, description string
	var price, cost float64

	err := db.QueryRow(
		"SELECT id, name, price, cost, description FROM products WHERE id = $1",
		productID,
	).Scan(&id, &name, &price, &cost, &description)

	if err != nil {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	name = strings.ReplaceAll(name, "\"", "\\\"")
	description = strings.ReplaceAll(description, "\"", "\\\"")
	w.Write([]byte(fmt.Sprintf(
		`{"id": %d, "name": "%s", "price": %.2f, "cost": %.2f, "description": "%s"}`,
		id, name, price, cost, description,
	)))
}

func main() {
	http.HandleFunc("/api/search", searchProducts)
	http.HandleFunc("/api/product", getProductDetail)
	fmt.Println("Starting server on :8080")
	http.ListenAndServe(":8080", nil)
}
